import React, { useContext } from 'react';
import { FormattedMessage } from 'react-intl';

import { Menu } from '../../navigation/menu/Menu.js';
import { DataTableContext } from '../contexts/DataTableContext.js';
import {
  _downloadAll,
  _downloadCurrentPage,
  noRowsSelected,
} from '../utils/download-utils.js';

export const DownloadDataMenuContents = () => {
  const {
    columns,
    hiddenColumns,
    data,
    page,
    paginationActive,
    selectableRowsActive,
    onDownloadData,
  } = useContext(DataTableContext);

  return (
    <Menu.Content>
      <Menu.Sub>
        <Menu.SubTrigger>
          <FormattedMessage
            defaultMessage="Download as CSV"
            id="TggAMlvVC8+HSDg6"
            description="Download table as CSV"
          />
        </Menu.SubTrigger>
        <Menu.SubContent>
          <Menu.Item
            onSelect={() => {
              _downloadAll(columns, hiddenColumns, data);
              onDownloadData?.('all');
            }}
          >
            <FormattedMessage
              defaultMessage="All"
              id="6DkhRjOwso7wlIuQ"
              description="Download the entire page"
            />
          </Menu.Item>
          {paginationActive && (
            <Menu.Item
              onSelect={() => {
                _downloadCurrentPage(page);
                onDownloadData?.('page');
              }}
            >
              <FormattedMessage
                defaultMessage="Current page"
                id="tSmzmDq7B63VRiyp"
                description="Download only the current page"
              />
            </Menu.Item>
          )}
          {selectableRowsActive && (
            <Menu.Item
              disabled={noRowsSelected(page)}
              onSelect={() => {
                _downloadCurrentPage(page, true);
                onDownloadData?.('selected');
              }}
            >
              <FormattedMessage
                defaultMessage="Selected"
                id="hHnZhEPC1euq8g/0"
                description="Download the selected rows"
              />
            </Menu.Item>
          )}
        </Menu.SubContent>
      </Menu.Sub>
    </Menu.Content>
  );
};
